 "content": "def transform(grid):
    """Copy the non-background pattern in the occupied compartment to all compartments."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Full monochrome lines in a non-background color mark compartment boundaries.
    # The most frequent non-divider color is the panel background.
    row_lines = [r for r in range(h) if len(set(g[r])) == 1]
    col_lines = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1]
    line_colors = {g[r][0] for r in row_lines} | {g[0][c] for c in col_lines}
    counts = {}
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color not in line_colors:
                counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get) if counts else 0

    # Ignore uniform lines of the background color; those are not dividers.
    row_cuts = [r for r in row_lines if g[r][0] != background]
    col_cuts = [c for c in col_lines if g[0][c] != background]
    row_bounds = [-1] + row_cuts + [h]
    col_bounds = [-1] + col_cuts + [w]
    panels = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            panels.append((r0, r1, c0, c1))

    # Choose the compartment with the most non-background cells as the pattern source.
    source = max(panels, key=lambda p: sum(
        g[r][c] != background
        for r in range(p[0], p[1]) for c in range(p[2], p[3])
    ))
    sr0, sr1, sc0, sc1 = source
    sh, sw = sr1 - sr0, sc1 - sc0
    for r0, r1, c0, c1 in panels:
        if r1 - r0 != sh or c1 - c0 != sw:
            continue
        for dr in range(sh):
            for dc in range(sw):
                g[r0 + dr][c0 + dc] = g[sr0 + dr][sc0 + dc]
    return g

if __name__ == '__main__':
